    }
    const auto=rest.match(/^<(https?:\/\/[^<>\s]+|mailto:[^<>\s]+)>/);
    if(auto) {out+='<a href="'+escapeHtml(auto[1])+'">'+escapeHtml(auto[1].replace(/^mailto:/,''))+'</a>';i+=auto[0].length;continue;}
