function renderBlocks(lines,context) {
  const out=[];
  const begins=i=>!!headingOf(lines[i])||!!fenceOf(lines[i])||!!listOf(lines[i])||/^ {0,3}>/.test(lines[i])||rule(lines[i])||(lines[i].includes('|')&&separator(lines[i+1]));
  for(let i=0;i<lines.length;) {
