  if (present.capture) await inspectCapture(state,python);
  if (present.request) await inspectRequest(state,original.base);
  if (present.operator) {
    await inspectOperator(state,original.base);
    await command(process.execPath,[join(original.base,BUYER),'--review-workspace','--dir',state.operator]);
  }
  console.log(JSON.stringify({status:'RAIL402_RECEIVING_REOPENED',directory:state.directory,intentId:state.input.intentId,present,
    response:present.response ? {path:join(state.request,'merchant-result.json'),bytes:(await lstat(join(state.request,'merchant-result.json'))).size} : null}));
