}
export const PROJECT_SCHEMA: 'stellar-forge.source-table-project.v1';
export const MAPPING_SCHEMA: 'stellar-forge.source-table-mapping.v1';
export const RESOURCE_SCHEMA: 'stellar-forge.tabular-resource.v1';
